<template>
  <div class="min-h-dvh bg-white pb-24">
    <header class="sticky top-0 z-20 bg-white border-b border-neutral-200">
      <div class="grid h-20 grid-cols-[1fr_auto_1fr] items-center px-4">
        <span></span>
        <div class="flex items-center gap-2 text-lg font-semibold">
          <button class="h-9 w-7 text-2xl text-neutral-400" @click="moveWeek(-1)" aria-label="上一周">‹</button>
          <button class="text-center" @click="pickerOpen = !pickerOpen">{{ rangeLabel }}</button>
          <button class="h-9 w-7 text-2xl text-neutral-400" @click="moveWeek(1)" aria-label="下一周">›</button>
        </div>
        <div class="justify-self-end flex items-center rounded-full bg-neutral-50 px-2 shadow-sm">
          <button class="h-12 w-12" @click="view = view === 'day' ? 'week' : 'day'" :aria-label="view === 'day' ? '切换为周视图' : '切换为日视图'"><svg viewBox="0 0 24 24" class="mx-auto h-7 w-7 fill-none stroke-current stroke-[2.5]"><rect x="3" y="4" width="7" height="7" rx="1"/><rect x="14" y="4" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 17.5h7M17.5 14v7"/></svg></button>
          <button class="h-12 w-12" @click="formOpen = true" aria-label="添加日程"><svg viewBox="0 0 24 24" class="mx-auto h-8 w-8 fill-none stroke-current stroke-[2.5]"><path d="M12 5v14M5 12h14"/></svg></button>
        </div>
      </div>
      <div v-if="pickerOpen" class="absolute left-4 right-4 top-16 z-30 rounded-xl bg-white p-4 shadow-xl border border-neutral-200"><label class="block text-xs text-neutral-500 mb-2">选择年份与周</label><input v-model="weekPicker" type="week" class="w-full rounded-lg bg-neutral-100 p-3" @change="applyWeek"></div>
      <div class="grid grid-cols-7 px-2 pb-2" @touchstart="swipeStart=$event.touches[0].clientX" @touchend="handleSwipe($event.changedTouches[0].clientX)">
        <button v-for="day in weekDays" :key="day.key" @click="selectedDate = day.key" class="flex flex-col items-center gap-1 text-xs" :class="day.key === selectedDate ? 'text-neutral-800 font-medium' : 'text-neutral-400'">
          <span>{{ day.name }}</span><span :class="day.isToday ? 'w-7 h-7 rounded-full bg-red-500 text-white flex items-center justify-center' : 'w-7 h-7 flex items-center justify-center'">{{ day.date }}</span>
        </button>
      </div>
      <div v-if="view === 'day'" class="grid grid-cols-[118px_1fr] border-t border-neutral-200 bg-white">
        <div class="border-r border-neutral-200"></div>
        <div class="py-3 text-center text-lg font-semibold" :class="selectedDay.isToday ? 'text-red-500' : 'text-neutral-800'">{{ selectedDay.month }}月{{ selectedDay.date }}日－周{{ selectedDay.name }}</div>
      </div>
    </header>

    <main v-if="view === 'day'" class="pb-28">
      <section v-if="allDay.length" class="border-t border-neutral-200"><div class="flex"><span class="w-[118px] shrink-0 pt-3 pr-4 text-right text-sm text-neutral-400">全天</span><div class="flex-1 border-l border-neutral-200 space-y-3 px-4 py-3"><div v-for="item in allDay" :key="item.id" @click="openEdit(item)" class="block w-full rounded-2xl border border-neutral-200 border-l-[7px] bg-[#f5f5f7] px-4 py-3 text-left shadow-sm" :class="[item.status==='completed' ? 'border-l-[#007aff] opacity-50' : 'border-l-[#ff9500]']"><span class="flex items-center gap-3"><span class="min-w-0 flex-1"><span class="block truncate text-xl font-semibold text-neutral-900" :class="item.status==='completed'?'line-through':''">{{ item.title }}</span></span><button type="button" @click.stop="toggle(item)" class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border-2" :class="item.status==='completed' ? 'border-[#007aff] text-[#007aff]' : 'border-[#ff9500] text-[#ff9500]'" :aria-label="item.status==='completed' ? `撤销完成 ${item.title}` : `完成 ${item.title}`">{{ item.status==='completed' ? '✓' : '' }}</button></span></div></div></div></section>
      <template v-for="block in dayTimeBlocks" :key="block.key">
        <div v-if="block.type === 'empty'" class="relative flex min-h-11 border-t border-neutral-200">
          <span class="w-[118px] shrink-0 pt-3 pr-4 text-right text-sm text-neutral-400">{{ block.startLabel }}</span>
          <div class="flex-1 border-l border-neutral-200 px-4 py-2 text-base text-neutral-500">空档已压缩 · {{ block.startLabel }}—{{ block.endLabel }}</div>
        </div>
        <div v-else class="flex border-t border-neutral-200">
          <span class="w-[118px] shrink-0 pt-3 pr-4 text-right text-sm text-neutral-400">{{ block.startLabel }}</span>
          <div class="flex-1 border-l border-neutral-200 space-y-3 px-4 py-3"><div v-for="item in block.items[selectedDate] || []" :key="item.id" @click="openEdit(item)" class="block w-full rounded-2xl border border-neutral-200 border-l-[7px] bg-[#f5f5f7] px-4 py-3 text-left shadow-sm" :class="[item.status==='completed' ? 'border-l-[#007aff] opacity-50' : 'border-l-[#ff9500]']"><span class="flex items-center gap-3"><span class="min-w-0 flex-1"><span class="block truncate text-xl font-semibold text-neutral-900" :class="item.status==='completed'?'line-through':''">{{ item.title }}</span><span class="mt-1 block text-base text-neutral-500">{{ item.start_time?.slice(0,5) }}–{{ item.end_time?.slice(0,5) }}</span><span v-if="item.overdue_reason" class="mt-1 block text-sm text-slate-500">逾期原因：{{ item.overdue_reason }}</span></span><button type="button" @click.stop="toggle(item)" class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border-2" :class="item.status==='completed' ? 'border-[#007aff] text-[#007aff]' : 'border-[#ff9500] text-[#ff9500]'" :aria-label="item.status==='completed' ? `撤销完成 ${item.title}` : `完成 ${item.title}`">{{ item.status==='completed' ? '✓' : '' }}</button></span></div></div>
        </div>
      </template>
    </main>
    <main v-else class="pb-28">
      <div class="grid grid-cols-[96px_repeat(2,minmax(0,1fr))] border-l border-t border-neutral-200 text-xs bg-white"><div class="border-r border-b border-neutral-200"></div><div v-for="d in detailDays" :key="d.key" class="border-r border-b border-neutral-200 py-3 text-center text-lg font-semibold" :class="d.isToday?'text-red-500':''">{{ d.month }}月{{ d.date }}日－周{{ d.name }}</div><template v-for="block in weekTimeBlocks" :key="block.key"><template v-if="block.type === 'empty'"><div class="min-h-11 border-r border-b border-neutral-200 pt-3 pr-3 text-right text-sm text-neutral-400">{{ block.startLabel }}</div><div v-for="d in detailDays" :key="d.key+block.key" class="min-h-11 border-r border-b border-neutral-200 px-2 py-2 text-neutral-500">空档已压缩<br><span class="text-[11px]">{{ block.startLabel }}—{{ block.endLabel }}</span></div></template><template v-else><div class="border-r border-b border-neutral-200 pt-3 pr-3 text-right text-sm text-neutral-400">{{ block.startLabel }}</div><div v-for="d in detailDays" :key="d.key+block.key" class="border-r border-b border-neutral-200 space-y-2 p-2"><div v-for="item in block.items[d.key] || []" :key="item.id" @click="openEdit(item)" class="block w-full rounded-xl border border-neutral-200 border-l-4 bg-[#f5f5f7] px-2 py-2 text-left shadow-sm" :class="[item.status==='completed' ? 'border-l-[#007aff] opacity-50' : 'border-l-[#ff9500]']"><span class="flex items-center gap-1"><span class="min-w-0 flex-1"><span class="block truncate text-sm font-semibold" :class="item.status==='completed'?'line-through':''">{{ item.title }}</span><span class="block text-xs text-neutral-500">{{ item.start_time?.slice(0,5) }}–{{ item.end_time?.slice(0,5) }}</span><span v-if="item.overdue_reason" class="mt-1 block text-[11px] text-slate-500">逾期原因：{{ item.overdue_reason }}</span></span><button type="button" @click.stop="toggle(item)" class="h-5 w-5 shrink-0 rounded-full border-2 text-center text-xs leading-4" :class="item.status==='completed' ? 'border-[#007aff] text-[#007aff]' : 'border-[#ff9500] text-[#ff9500]'" :aria-label="item.status==='completed' ? `撤销完成 ${item.title}` : `完成 ${item.title}`">{{ item.status==='completed' ? '✓' : '' }}</button></span></div></div></template></template></div>
    </main>
    <button @click="goToday" class="fixed bottom-24 left-5 z-20 rounded-full bg-white px-4 py-2 text-sm font-medium text-neutral-700 shadow-lg ring-1 ring-neutral-200">今天</button>
    <div v-if="overdueItem" class="fixed inset-0 z-[70] flex items-end bg-black/30" @click.self="cancelOverdue"><form @submit.prevent="confirmOverdue" class="w-full rounded-t-2xl bg-white p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))]"><h2 class="text-lg font-semibold">逾期完成</h2><p class="mt-2 text-sm text-neutral-500">可填写完成延迟的原因。</p><textarea v-model="overdueReason" rows="3" maxlength="500" placeholder="填写原因（可选）" class="mt-4 w-full rounded-xl bg-neutral-100 p-3 text-sm"/><div class="mt-4 flex gap-3"><button type="button" @click="cancelOverdue" class="flex-1 rounded-xl bg-neutral-100 py-3">取消</button><button type="submit" class="flex-1 rounded-xl bg-[#007aff] py-3 font-medium text-white">确认完成</button></div></form></div>
    <div v-if="editingItem" class="fixed inset-0 z-[60] flex items-end bg-black/30" @click.self="closeEdit"><form @submit.prevent="saveEdit" class="w-full max-h-[92dvh] overflow-y-auto rounded-t-2xl bg-white p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))] space-y-3"><div class="flex items-center justify-between"><h2 class="text-lg font-semibold">编辑日程</h2><div class="flex items-center gap-4 text-sm"><button type="button" class="text-red-500" @click="deleteConfirm=true">删除</button><button type="button" @click="closeEdit">关闭</button><button type="submit" class="font-medium text-[#007aff]">保存</button></div></div><input v-model="editForm.title" required maxlength="200" placeholder="任务名称" class="w-full rounded-lg bg-neutral-100 p-3 text-sm"><label class="flex gap-2 text-sm"><input type="checkbox" v-model="editForm.is_all_day"> 全天</label><template v-if="!editForm.is_all_day"><input v-model="editForm.start_time" type="time" required class="w-full rounded-lg bg-neutral-100 p-3 text-sm"><input v-model="editForm.end_time" type="time" required class="w-full rounded-lg bg-neutral-100 p-3 text-sm"></template><template v-if="editingItem.recurrence_type !== 'NONE'"><p class="pt-2 text-sm text-neutral-600">应用范围</p><div class="grid grid-cols-2 gap-2"><button type="button" @click="editScope='single'" class="rounded-xl border p-3 text-sm" :class="editScope==='single'?'border-[#007aff] text-[#007aff]':'border-neutral-200'">仅修改本次</button><button type="button" @click="editScope='following'" class="rounded-xl border p-3 text-sm" :class="editScope==='following'?'border-[#007aff] text-[#007aff]':'border-neutral-200'">本次及后续</button></div></template><p v-if="editError" class="text-sm text-red-600">{{ editError }}</p><template v-if="deleteConfirm"><p class="pt-3 text-sm text-neutral-600">{{ editingItem.recurrence_type === 'NONE' ? '删除后不可恢复。' : '请选择删除范围。' }}</p><div v-if="editingItem.recurrence_type !== 'NONE'" class="grid grid-cols-2 gap-2"><button type="button" @click="deleteScope='single'" class="rounded-xl border p-3 text-sm" :class="deleteScope==='single'?'border-[#007aff] text-[#007aff]':'border-neutral-200'">仅本次</button><button type="button" @click="deleteScope='following'" class="rounded-xl border p-3 text-sm" :class="deleteScope==='following'?'border-[#007aff] text-[#007aff]':'border-neutral-200'">本次及后续</button></div><button type="button" @click="removeSchedule" class="w-full rounded-xl bg-red-500 py-3 font-medium text-white">确认删除</button></template></form></div>
    <div v-if="formOpen" class="fixed inset-0 z-[60] bg-black/30 flex items-end"><form @submit.prevent="create" class="w-full max-h-[92dvh] overflow-y-auto rounded-t-2xl bg-white p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))] space-y-3"><div class="flex justify-between"><h2 class="font-medium">添加日程</h2><div class="flex items-center gap-4 text-sm"><button type="button" @click="formOpen=false">关闭</button><button type="submit" class="font-medium text-[#007aff]">保存</button></div></div><input v-model="form.title" required maxlength="200" placeholder="任务名称" class="w-full rounded-lg bg-neutral-100 p-3 text-sm"><label class="flex gap-2 text-sm"><input type="checkbox" v-model="form.is_all_day"> 全天</label><input v-model="form.start_date" :min="todayKey" type="date" class="w-full rounded-lg bg-neutral-100 p-3 text-sm"><template v-if="!form.is_all_day"><input v-model="form.start_time" type="time" required class="w-full rounded-lg bg-neutral-100 p-3 text-sm"><input v-model="form.end_time" type="time" required class="w-full rounded-lg bg-neutral-100 p-3 text-sm"></template><select v-model="form.recurrence_type" class="w-full rounded-lg bg-neutral-100 p-3 text-sm"><option value="NONE">单次</option><option value="DAILY">每天</option><option value="WEEKLY">每周</option></select><p v-if="formError" class="text-sm text-red-600">{{ formError }}</p></form></div>
  </div>
</template>

<script setup lang="ts">
import type { ScheduleOccurrence } from '~/types'
definePageMeta({ layout: 'default', middleware: 'auth' })
const { api } = useApi(); const now = new Date(); const selectedDate = ref(now.toISOString().slice(0,10)); const weekStart = ref(new Date(now)); weekStart.value.setDate(now.getDate() - now.getDay())
const view = ref<'day'|'week'>('day'); const items = ref<ScheduleOccurrence[]>([]); const loading = ref(false); const formOpen = ref(false); const formError = ref(''); const pickerOpen = ref(false); const swipeStart = ref(0); const weekPicker = ref(''); const editingItem = ref<ScheduleOccurrence|null>(null); const deleteConfirm = ref(false); const deleteScope = ref<'single'|'following'>('single'); const editScope = ref<'single'|'following'>('single'); const editError = ref(''); const editForm = reactive({title:'',is_all_day:false,start_time:'09:00',end_time:'10:00'}); const overdueItem = ref<ScheduleOccurrence|null>(null); const overdueReason = ref('')
const form = reactive({ title:'', is_all_day:false, start_date:selectedDate.value, start_time:'09:00', end_time:'10:00', recurrence_type:'NONE' })
const dateKey=(d:Date)=>d.toISOString().slice(0,10); const todayKey=dateKey(now); const weekDays=computed(()=>Array.from({length:7},(_,i)=>{const d=new Date(weekStart.value);d.setDate(d.getDate()+i);return {key:dateKey(d),date:d.getDate(),month:d.getMonth()+1,name:['日','一','二','三','四','五','六'][i],isToday:dateKey(d)===dateKey(now)}})); const selectedIndex=computed(()=>Math.max(0,weekDays.value.findIndex(d=>d.key===selectedDate.value))); const selectedDay=computed(()=>{const found=weekDays.value.find(d=>d.key===selectedDate.value);if(found)return found;const d=new Date(`${selectedDate.value}T00:00:00`);return {key:selectedDate.value,date:d.getDate(),month:d.getMonth()+1,name:['日','一','二','三','四','五','六'][d.getDay()],isToday:selectedDate.value===dateKey(now)}}); const detailDays=computed(()=>weekDays.value.slice(selectedIndex.value, selectedIndex.value+2).length===2?weekDays.value.slice(selectedIndex.value, selectedIndex.value+2):weekDays.value.slice(5,7)); const rangeLabel=computed(()=>`${weekDays.value[0].key.slice(0,4)}年${weekDays.value[0].month}月${weekDays.value[0].date}日-${weekDays.value[6].month}月${weekDays.value[6].date}日`); const hours=Array.from({length:18},(_,i)=>i+5)
const todayItems=computed(()=>items.value.filter(x=>x.scheduled_date===selectedDate.value)); const allDay=computed(()=>todayItems.value.filter(x=>x.is_all_day)); const timeToMinute=(time?:string|null)=>{const [hour,minute]=(time||'00:00').split(':').map(Number);return hour*60+minute}; const minuteLabel=(minute:number)=>`${String(Math.floor(minute/60)).padStart(2,'0')}:${String(minute%60).padStart(2,'0')}`
type TimelineBlock={type:'empty',key:string,startLabel:string,endLabel:string}|{type:'tasks',key:string,startLabel:string,items:Record<string,ScheduleOccurrence[]>}
const buildTimeBlocks=(days:string[]):TimelineBlock[]=>{const scheduleItems=items.value.filter(item=>days.includes(item.scheduled_date)&&!item.is_all_day&&item.start_time&&item.end_time);const boundaries=new Set([300,1380]);scheduleItems.forEach(item=>{boundaries.add(timeToMinute(item.start_time));boundaries.add(timeToMinute(item.end_time))});const points=[...boundaries].filter(point=>point>=300&&point<=1380).sort((a,b)=>a-b);return points.flatMap((point,index)=>{const starting=scheduleItems.filter(item=>timeToMinute(item.start_time)===point);if(starting.length){const grouped=Object.fromEntries(days.map(day=>[day,starting.filter(item=>item.scheduled_date===day)]));return [{type:'tasks' as const,key:`tasks-${point}`,startLabel:minuteLabel(point),items:grouped}]}const next=points[index+1];return next?[{type:'empty' as const,key:`empty-${point}-${next}`,startLabel:minuteLabel(point),endLabel:minuteLabel(next)}]:[]})}
const dayTimeBlocks=computed(()=>buildTimeBlocks([selectedDate.value]))
const weekTimeBlocks=computed(()=>buildTimeBlocks(detailDays.value.map(day=>day.key)))
async function load(){loading.value=true;try{items.value=await api<ScheduleOccurrence[]>(`/schedules?start_date=${weekDays.value[0].key}&end_date=${weekDays.value[6].key}`)}finally{loading.value=false}} function moveWeek(delta:number){const d=new Date(weekStart.value);d.setDate(d.getDate()+delta*7);weekStart.value=d;selectedDate.value=dateKey(d);load()} function goToday(){const d=new Date(now);d.setDate(now.getDate()-now.getDay());weekStart.value=d;selectedDate.value=todayKey;load()} function handleSwipe(end:number){if(Math.abs(end-swipeStart.value)>45)moveWeek(end<swipeStart.value?1:-1)} function applyWeek(){const [year,week]=weekPicker.value.split('-W').map(Number);if(!year||!week)return;const jan4=new Date(year,0,4);const monday=new Date(jan4);monday.setDate(jan4.getDate()-((jan4.getDay()+6)%7)+(week-1)*7);monday.setDate(monday.getDate()-1);weekStart.value=monday;selectedDate.value=dateKey(monday);pickerOpen.value=false;load()} const isOverdue=(item:ScheduleOccurrence)=>item.is_all_day?new Date(`${item.scheduled_date}T23:59:59`)<new Date():!!item.end_time&&new Date(`${item.scheduled_date}T${item.end_time}`)<new Date(); async function complete(item:ScheduleOccurrence,reason?:string){const updated=await api<ScheduleOccurrence>(`/schedules/occurrences/${item.id}/completion`,{method:'PUT',body:{completed:item.status!=='completed',overdue_reason:reason}});items.value=items.value.map(x=>x.id===item.id?updated:x)} async function toggle(item:ScheduleOccurrence){if(item.status==='completed'){await complete(item);return}if(isOverdue(item)){overdueItem.value=item;overdueReason.value='';return}await complete(item)} async function confirmOverdue(){if(!overdueItem.value)return;await complete(overdueItem.value,overdueReason.value||undefined);cancelOverdue()} function cancelOverdue(){overdueItem.value=null;overdueReason.value=''} function openEdit(item:ScheduleOccurrence){editingItem.value=item;deleteConfirm.value=false;deleteScope.value='single';editScope.value='single';editError.value='';editForm.title=item.title;editForm.is_all_day=item.is_all_day;editForm.start_time=item.start_time?.slice(0,5)||'09:00';editForm.end_time=item.end_time?.slice(0,5)||'10:00'} function closeEdit(){editingItem.value=null;deleteConfirm.value=false;editError.value=''} async function saveEdit(){if(!editingItem.value)return;editError.value='';try{await api(`/schedules/occurrences/${editingItem.value.id}`,{method:'PUT',body:{...editForm,start_time:editForm.is_all_day?null:editForm.start_time,end_time:editForm.is_all_day?null:editForm.end_time,scope:editScope.value}});closeEdit();await load()}catch(error:any){editError.value=error?.data?.detail || '保存失败，请检查填写内容'}} async function removeSchedule(){if(!editingItem.value)return;await api(`/schedules/occurrences/${editingItem.value.id}?scope=${deleteScope.value}`,{method:'DELETE'});closeEdit();await load()} async function create(){formError.value='';try{await api('/schedules',{method:'POST',body:form});formOpen.value=false;form.title='';await load()}catch(error:any){formError.value=error?.data?.detail || '保存失败，请检查填写内容'}} watch(selectedDate,v=>form.start_date=v); onMounted(load)
</script>
